(* [comment removed for export] *)
Ltac x2len := rewrite ?upd_bytes_length by (rewrite ?ox2_length; cbn [length]; lia); rewrite ?ox2_length; cbn [length]; lia.

Ltac xh DT4 ARR q :=
  let SOK := fresh "SOK" in
  pose proof (u8arr_store_ok_n usegs _ DT4 _ q 2 (wa (DT4 + q)) ARR ltac:(lia) ltac:(x2len) eq_refl) as SOK;
  zstep;
  lazymatch goal with
  | |- evt _ _ (MS _ _ _ _ _ (write_to_mem _ (wa ?E) _) _) => replace E with (DT4 + q) by lia
  | |- evt _ _ (MS _ _ _ _ _ (write_to_mem _ (Z_to_bv 64 ?E) _) _) => replace E with (DT4 + q) by lia
  end;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ (write_to_mem _ _ (le2 ?x)) _) =>
    match goal with H : le2 x = [_; _] |- _ => rewrite H end
  end;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ (write_to_mem _ _ ?bb) _) =>
    let ARR2 := fresh "ARR" in
    pose proof (u8arr_write_bytes usegs _ DT4 _ q bb ARR ltac:(lia) ltac:(x2len)) as ARR2;
    clear ARR; store_done; rename ARR2 into ARR
  end.

(* [comment removed for export] *)
(* [comment removed for export] *)
Ltac xcell DT4 ARR u :=
  xh DT4 ARR (4 * u); xh DT4 ARR (4 * u + 2);
  replace (Z.to_nat (4 * u)) with (4 * Z.to_nat u)%nat in ARR by lia;
  replace (Z.to_nat (4 * u + 2)) with (4 * Z.to_nat u + 2)%nat in ARR by lia;
  rewrite ox2_store in ARR by (rewrite ?oset2_length by lia; lia).

(* [comment removed for export] *)
Ltac xcell_rev DT4 ARR u :=
  xh DT4 ARR (4 * u + 2); xh DT4 ARR (4 * u);
  replace (Z.to_nat (4 * u)) with (4 * Z.to_nat u)%nat in ARR by lia;
  replace (Z.to_nat (4 * u + 2)) with (4 * Z.to_nat u + 2)%nat in ARR by lia;
  rewrite ox2_store_rev in ARR by (rewrite ?oset2_length by lia; lia).

